const jolpicaRace = $('Jolpica – Race Results').first().json?.MRData?.RaceTable?.Races?.[0] || {};

const jolpicaQuali = $('Jolpica – Qualifying').first().json?.MRData?.RaceTable?.Races?.[0]?.QualifyingResults || [];

const jolpicaDriverS = $('Jolpica – Driver Standings').first().json?.MRData?.StandingsTable?.StandingsLists?.[0]?.DriverStandings || [];

const jolpicaConstrS = $('Jolpica – Constructor Standings').first().json?.MRData?.StandingsTable?.StandingsLists?.[0]?.ConstructorStandings || [];

const jolpicaPits = $('Jolpica – Pit Stops').first().json?.MRData?.RaceTable?.Races?.[0]?.PitStops || [];

const schedule = $('Jolpica – Season Schedule').first().json?.MRData?.RaceTable?.Races || [];


// ================== RESULTS ==================

const results = (jolpicaRace.Results || []).map(r => {

  const q = Array.isArray(jolpicaQuali)
    ? jolpicaQuali.find(q => q.Driver?.driverId === r.Driver?.driverId)
    : null;

  const grid = parseInt(r.grid || 0);
  const pos  = parseInt(r.position || 0);

  return {
    position: pos,
    gridPosition: grid,
    positionsGained: grid - pos,

    driver: (r.Driver?.givenName || '') + ' ' + (r.Driver?.familyName || ''),
    driverId: r.Driver?.driverId || '',
    nationality: r.Driver?.nationality || '',

    constructor: r.Constructor?.name || '',

    points: parseFloat(r.points || 0),
    status: r.status || '',

    fastestLap: r.FastestLap || null,

    qualifyingTime: q ? (q.Q3 || q.Q2 || q.Q1 || 'N/A') : 'N/A',

    time: r.Time?.time || r.status
  };
});


// ================== INSIGHTS ==================

const biggestMover = [...results]
  .filter(r => r.positionsGained > 0)
  .sort((a, b) => b.positionsGained - a.positionsGained)[0] || null;

const fastestLapHolder = results.find(r => r.fastestLap?.rank === '1') || null;

const dnfs = results.filter(r =>
  r.status &&
  r.status !== 'Finished' &&
  !r.status.startsWith('+')
);


// ================== SEASON ==================

const currentRound = parseInt(jolpicaRace.round || '0');
const totalRaces = Array.isArray(schedule) ? schedule.length : 0;
const racesLeft = totalRaces - currentRound;


// ================== OUTPUT ==================

return [{
  json: {

    race: {
      name: jolpicaRace.raceName || 'Unknown Race',
      season: jolpicaRace.season || new Date().getFullYear(),
      round: jolpicaRace.round || '?',

      circuit: jolpicaRace.Circuit?.circuitName || 'Unknown Circuit',
      country: jolpicaRace.Circuit?.Location?.country || '',
      city: jolpicaRace.Circuit?.Location?.locality || '',

      date: jolpicaRace.date || new Date().toISOString().split('T')[0]
    },

    results: results.slice(0, 20),
    podium: results.slice(0, 3),
    winner: results[0] || {},

    biggestMover,
    fastestLapHolder,
    dnfs,

    pitstops: Array.isArray(jolpicaPits) ? jolpicaPits : [],
    qualifying: Array.isArray(jolpicaQuali) ? jolpicaQuali.slice(0, 10) : [],

    driverStandings: jolpicaDriverS,
    constructorStandings: jolpicaConstrS,

    // ✅ CLEAN DATA FOR AI
    driverStandingsTop5: jolpicaDriverS.slice(0,5),
    constructorStandingsTop4: jolpicaConstrS.slice(0,4),

    season: {
      totalRaces,
      currentRound,
      racesLeft,
      pointsLeft: racesLeft * 26
    }
  }
}];

function parseAI(nodeName) {
  try {
    const raw = $node[nodeName].json.content[0].text;
    return JSON.parse(raw.replace(/```json|```/g, '').trim());
  } catch(e) {
    return { _parseError: true, _node: nodeName };
  }
}
const analysis     = parseAI('AI – Race Analysis');
const championship = parseAI('AI – Championship Analysis');
const payload      = $('Build Unified Payload').item.json;
return [{ json: { analysis, championship, payload } }];

