const raw = $input.first().json;

// Safe data extraction
const podium = raw.payload?.podium || [];
const race = raw.payload?.race || {};
const winner = raw.payload?.winner || {};
const fastestLap = raw.payload?.fastestLapHolder || {};
const biggestMover = raw.payload?.biggestMover || {};
const championship = raw.championship || {};

// Safer DNF handling
const dnfs = raw.payload?.dnfs?.filter(d => d.status === 'Retired')
  .map(d => d.driver)
  .join(', ') || 'None';

// Build prompt
const prompt = `
You are an elite motorsport journalist AND a professional email UI designer.

Your task is to generate a visually stunning, modern HTML email newsletter for a Formula 1 race.

=====================
CRITICAL INSTRUCTIONS
=====================
- You MUST include ALL sections
- You MUST NOT stop early
- Minimum output length: 900 words
- Output MUST be complete valid HTML ending with </html>
- Use ONLY inline CSS (no external styles)
- Dark theme (black/grey background, red #dc0000 accents)
- Clean spacing, card layout, premium feel

=====================
STRUCTURE (MANDATORY)
=====================
Include ALL of these sections with clear visual separation:

1. HEADER
2. RACE INFO
3. PODIUM (3 columns)
4. RACE HIGHLIGHTS
5. CHAMPIONSHIP
6. FOOTER

If any section is missing, the output is INVALID.

=====================
CONTENT RULES
=====================
- Winner story MUST be at least 150 words
- Write like a real F1 journalist (insight, narrative, race dynamics)
- No bullet spam
- No raw JSON repetition
- Use strong typography hierarchy in HTML

=====================
RACE DATA
=====================
Race: ${race.name} ${race.season}
Round: ${race.round}
Circuit: ${race.circuit}
Location: ${race.city}, ${race.country}
Date: ${race.date}

=====================
PODIUM
=====================
1st: ${podium[0]?.driver} (${podium[0]?.nationality}) — ${podium[0]?.time}
2nd: ${podium[1]?.driver} — ${podium[1]?.time}
3rd: ${podium[2]?.driver} — ${podium[2]?.time}

=====================
HIGHLIGHTS
=====================
Winner started: P${winner.gridPosition}
Fastest Lap: ${fastestLap?.driver} — ${fastestLap?.fastestLap?.Time?.time}
Biggest Mover: ${biggestMover?.driver} (+${biggestMover?.positionsGained} places, P${biggestMover?.gridPosition}→P${biggestMover?.position})
DNFs: ${dnfs}

=====================
CHAMPIONSHIP
=====================
WDC Leader: ${championship.wdc_leader} (+${championship.wdc_gap} pts over ${championship.wdc_second})
WDC Story: ${championship.wdc_narrative}

WCC Leader: ${championship.wcc_leader} (+${championship.wcc_gap} pts)
WCC Story: ${championship.wcc_narrative}

Races Remaining: ${championship.races_remaining}
Points Available: ${championship.points_available}

=====================
FINAL OUTPUT RULE
=====================
Return ONLY the HTML. No explanations. No markdown.
`;

const body = {
  model: "claude-haiku-4-5-20251001", // 
  max_tokens: 4000, // more breathing room
  messages: [
    {
      role: "user",
      content: prompt
    }
  ]
};

return [{ json: { body } }];

